create table if not exists public.messages (id uuid primary key default gen_random_uuid(), name text not null check (char_length(btrim(name)) between 1 and 30), wechat text not null check (char_length(btrim(wechat)) between 1 and 50), content text not null check (char_length(btrim(content)) between 1 and 2000), created_at timestamptz not null default now(), is_read boolean not null default false, read_at timestamptz, deleted_at timestamptz);
create table if not exists public.page_views (id bigint generated by default as identity primary key, visitor_id text not null, path text not null, created_at timestamptz not null default now());
alter table public.messages enable row level security; alter table public.page_views enable row level security;
create policy "public can submit messages" on public.messages for insert to anon, authenticated with check (deleted_at is null and is_read = false);
create policy "public can record views" on public.page_views for insert to anon, authenticated with check (char_length(visitor_id) between 16 and 64);
create policy "admins read messages" on public.messages for select to authenticated using ((select auth.jwt() ->> 'email') = 'chenziying62@proton.me' and deleted_at is null);
create policy "admins update messages" on public.messages for update to authenticated using ((select auth.jwt() ->> 'email') = 'chenziying62@proton.me') with check ((select auth.jwt() ->> 'email') = 'chenziying62@proton.me');
create policy "admins delete messages" on public.messages for delete to authenticated using ((select auth.jwt() ->> 'email') = 'chenziying62@proton.me');
create policy "admins read views" on public.page_views for select to authenticated using ((select auth.jwt() ->> 'email') = 'chenziying62@proton.me');
